const GDATA=[{"name":"حروف التهجي العربية","items":[{"t":"تدريب (١)","q":"رتب الأسماء التالية على وفق الأرقام التي تقابلها بعدد أحرفها، كما في المثال: (يد، إستبرق، سفرجل، أسد، مرمى، كتاب)."},{"t":"تدريب (٢)","q":"صل بين الاسمين المتشابهين بالحروف: (غريب / مازن، ربيع / يغرب، ملح / عبير، زمان / لحم)."},{"t":"تدريب (٣)","q":"اكتب في الفراغ الأحرف التي تتكون منها الكلمة رسماً واسماً متبعاً المثال الأول (من): (فيل، سماء، ورقة، حديقة، رجع)."},{"t":"تدريب (٤)","q":"لاحظ المثال واكتب كلمات على وفق المثال (٣: جمل، ٤: المشي، ٢: لام)."}]},{"name":"الضوابط والحركات الإعرابية","items":[{"t":"تدريب (١)","q":"اقرأ الكلمات التالية ثم اكتبها بشكلها الصحيح كما هو موضح في المثال (شدّاد = بسّام): (سلام، برّاز، درّب، بنّاء، خطّين، قدّوري، الشّمس، عوّاد)."},{"t":"تدريب (٢)","q":"اقرأ وأكمل كما في المثال السابق (ضوء الشمس، نور القمر): (مفتاح / الباب، باب / الدار، عين / الوز، علم / العراق)."},{"t":"تدريب (٣)","q":"اقرأ وأكمل كما في المثال السابق (قرءان = قرآن، اباء = آباء): (ءايات، آمين، آخر، مآرب، مآدب، آمال، عامئة، آدم، عاب، ءاثار)."},{"t":"تدريب (٤)","q":"أ - ضع العلامة التي تناسب نطق صوت الراء في الكلمات الآتية: (رباب: الراء مفتوح، رداء: الراء مكسور، رمان: الراء مضموم، مرمى: الراء ساكن).\nب - ضع العلامة المناسبة لنطق حرف الصاد (الفتحة أو الضمة أو الكسرة أو السكون) في الكلمات الآتية: (صنع - صندوق - صناعة - مصنع)."}]},{"name":"الحروف الشمسية والحروف القمرية","items":[{"t":"تدريب (١)","q":"ضع اسماً مناسباً من الأسماء التالية في المكان الخالي بعد إدخالك عليه (الـ) وضع شدة على الحرف الذي يلي (لام) الـ التي لا تلفظ في أثناء القراءة (شتاء، مطر، شمس، قمر، صبر، حديقة، جار):\n1. حر ..... شديد.\n2. ذهب ..... وجاء الربيع.\n3. هطل ..... من الغيوم.\n4. طلع .... بين النجوم.\n5. سل عن ..... قبل الدار.\n6. عود نفسك .....\n7. لعب الأطفال في ....."},{"t":"تدريب (٢)","q":"ميز الكلمات التي تتضمن حروفاً شمسية من الكلمات التي تتضمن حروفاً قمرية: (الصديق، الحانوت، العشب، الورد، الشجر، القطار، البركة، الخشب، النمر، الماء)."},{"t":"تدريب (٣)","q":"اقرأ النص التالي ثم اكتب الكلمات التي تحوي كل منها حرفاً شمسياً: («في فصل الخريف ينضج التفاح والعنب والرمان والكمثرى ويثمر الزيتون ويُقطف القطن. ويبدأ الفلاح بحراثة الأرض، ويعود إلى بيته في المساء ويساعده أبناؤه في عمله بعد الانتهاء من واجباتهم المدرسية»)."},{"t":"تدريب (٤)","q":"أدخل (الـ) على كل اسم مما يلي والفظه ثم اكتبه، ثم بين ما كان منها حرفاً شمسياً أو حرفاً قمرياً: (عنب، مدرسة، صيف، خيار، ثوم، هدهد، زبيب، سفينة، طريق، ورد، تلميذ، حديقة، ضيف، فيل)."}]},{"name":"أقسام الكلام","items":[{"t":"تدريب (١)","q":"ضع اسماً مناسباً في المكان الخالي:\n1. يريد ......... الحرية.\n2. يحتفل ......... بعيد الجيش.\n3. ......... يدعو إلى المحبة.\n4. ......... جزء من الوطن العربي."},{"t":"تدريب (٢)","q":"أكمل كل جملة من الجمل التالية بفعل مناسب من الأفعال المحصورة بين قوسين:\n1. الدجاجة الحب ......... (تشرب - تلتقط).\n2. ......... على البيض (ترقد - تدوس).\n3. ......... البيض بعد مدة (يذوب - يفقس).\n4. لحم الدجاج ......... (يضر - ينفع)."},{"t":"تدريب (٣)","q":"ضع حرفاً مناسباً في المكان الخالي من الجمل الآتية: (أضع الكتب ....... الحقيبة، وأذهب ....... المدرسة، أسير ....... الرصيف الأيمن، وألعب ....... ساحة المدرسة، وأنتبه ....... المعلم عند الشرح، وبعد الظهر أعود ....... البيت)."},{"t":"تدريب (٤)","q":"استخرج الأسماء والأفعال والحروف من الجمل التالية وضعها في المكان المناسب من الجدول:\n1. قال الله تعالى: (إِنَّ اللَّهَ يَأْمُرُ بِالعَدْلِ) [النحل / ٩٠].\n2. اطلب العلم من المهد إلى اللحد.\n3. اسمع نصيحة المعلم.\n4. يرفع الله المتواضع."}]},{"name":"المذكر والمؤنث","items":[{"t":"تدريب (١)","q":"وزع الكلمات التالية على جدولين: الأول خاص بالمذكر، والثاني خاص بالمؤنث: (زيد، زينب، سعاد، معلمة، مهندس، أب، أم، طويل، مؤدبة، جندي)."},{"t":"تدريب (٢)","q":"وزع أسماء الحيوانات التالية على جدولين: الأول يخص المذكر، والثاني يخص المؤنث: (جمل، قطة، عصفور، خروف، دجاجة، أسد، ثعلب، حية، أرنب)."},{"t":"تدريب (٣)","q":"وزع أسماء النباتات التالية على جدولين: الأول يخص المذكر والثاني يخص المؤنث: (شجرة، نخلة، زيتون، رز، تفاحة، عنب، جزرة، تين، رمان)."},{"t":"تدريب (٤)","q":"اكتب خمسة أسماء لمذكر جماد، وخمسة آخر لمؤنث من غير الإنسان."},{"t":"تدريب (٥)","q":"صل كل اسم مذكر في العمود الأول بما يناسبه من اسم مؤنث في العمود الثاني: (ثور، خروف، ديك، هر، جمل، أب، أسد) مع (دجاجة، امرأة، لبؤة، ناقة، نعجة، بقرة، قطة)."},{"t":"تدريب (٦)","q":"حول الاسم المذكر إلى مؤنث بزيادة تاء (ة) في نهاية الاسم المذكر (ابن -> ابنة): (معلم، موظف، تلميذ، طويل، مناضل، مخلص، عادل، ناجح)."},{"t":"تدريب (٧)","q":"حول العبارات التالية من المؤنث إلى المذكر:\n1. عادت التلميذة من المدرسة.\n2. المذيعة واضحة الصوت.\n3. المعلمة مخلصة في عملها.\n4. دافعت المحامية عن المتهم.\n5. فازت اللاعبة بالجائزة.\n6. كرمت المديرة الطالبة المجدة.\n7. الطبيبة تداوي المريضة.\n8. دخلت الدجاجة إلى القفص.\n9. حصدت الفلاحة الزرع.\n10. شكرت البنت أمها."},{"t":"تدريب (٨)","q":"اجعل الدعاء التالي لأبيك بدلاً من أمك: («اللهم ارض عن أمي، ووفقها في حياتها، وامنحها الصحة والعافية، واجعلها سعيدة، واملأ قلبها بالإيمان، اللهم أعني على رد جميلها، إنك تجيب دعوة الداعي إذا دعاك»)."},{"t":"تدريب (٩)","q":"حول الكلام التالي إلى المذكر بدلاً من المؤنث: («سميرة بنت مؤدبة، تذهب إلى المدرسة كل صباح، وتعود منها بعد الظهر، وهي محبوبة بين أهلها»)."},{"t":"تدريب (١٠)","q":"اختر لكل كلمة من كلمات العمود الأول (الزرع، الشجرة، المدينة، الجندي، الشمس) وصفاً يناسبها من العمود الثاني (المثمرة، الشجاع، الطالعة، الكبيرة، الأخضر) ثم أكمل الجملة بعبارة من العمود الثالث (خيرها وافر، يحمي الوطن، ضوءها ساطع، شوارعها واسعة، تربته خصبة)."},{"t":"تدريب (١١)","q":"كون جملاً مفيدة من كلمات العمود الأول (المعلم، الكتاب، المئذنة، الطالبة) مع ما يناسبها من كلمات العمود الثاني (مفيد، مخلص، مهذبة، طويلة) كما في المثال (القمر منير)."}]},{"name":"المفرد والمثنى والجمع","items":[{"t":"تدريب (١)","q":"أكمل الجدول بالمفرد والمثنى والجمع للكلمات التالية: (كتاب، دجاجة، قلم، فلاح)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بكتابة كلمة مناسبة:\nأ - الفلاح ذاهب إلى حقله. ......... ذاهبان إلى حقلهما. ......... ذاهبون إلى حقلهم.\nب - الطبيب يعالج المرضى. ......... يعالجان المرضى. ...... يعالجون المرضى.\nج - البنت تغزل الصوف. ....... تغزلان الصوف. ........ يغزلن الصوف.\nد - الجندي يدافع عن الوطن. ......... يدافعان عن الوطن. ........ يدافعون عن الوطن."},{"t":"تدريب (٣)","q":"صنف الأسماء التالية بحسب الجدول إلى مفرد أو مثنى أو جمع: (كتاب، مجلات، مجتهدان، قلم، فلاحون، طيارتان، صقر، حمامتان، فرات، رافدان، أمهات، ولد، عامل، دفتران، عجلات، إطاران، زائرات، عالم، أولاد)."},{"t":"تدريب (٤)","q":"أكمل الجمل التالية على وفق المثال:\nأ - الفلاح يغرس الشجرة. الفلاحان ......... الفلاحون .........\nب - المهندس ينجز المشروع. المهندسان ......... المهندسون .........\nج - المجتهدة تكتب الواجب. المجتهدتان ......... المجتهدات ........."},{"t":"تدريب (٥)","q":"اختر المفردة المناسبة مما بين القوسين لإكمال الجمل الآتية:\nالتفاحتان ......... (لذيذة، لذيذتان، لذيذات).\nالتلميذات ......... (مؤدبة، مؤدبتان، مؤدبات).\nالشارع ......... (طويلان، طويل، طويلة).\nالسائقون ......... (متدربات، متدرب، متدربون).\nالنافذتان ......... (مفتوحة، مفتوحات، مفتوحتان).\nالشجرتان ......... (مثمرة، مثمرتان، مثمرات)."},{"t":"تدريب (٦)","q":"نشاط صفي بالبطاقات يربط بين أسماء (المفرد، المثنى، الجمع) والعبارات المكملة لمعناها، مثل: (الطبيبة تداوي المرضى / الطبيبتان تداويان المرضى / الطبيبات يداوين المرضى)."},{"t":"تدريب (٧)","q":"اقرأ ثم أكمل جدول المفرد والمثنى والجمع: (ولد، شجرة، تلميذ، قدم، تلميذة، ورقة، نهر، غصن، علم، زهرة، قلم، سفينة، صفحة، حمامة، صياد، مسافر، مؤمن)."}]},{"name":"أسماء الإشارة","items":[{"t":"تدريب (١)","q":"قراءة وملاحظة مجموعات أسماء الإشارة للقريب والمتوسط والبعيد (هذا، هذان، هؤلاء، هذه، هاتان، ذاك، ذلك، تلك، أولئك)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بكتابة (هذا) أو (هذه) أو (هذان) أو (هاتان) في الفراغات الآتية:\n1. ......... الدرس مفيد.\n2. ......... السماء صافية.\n3. ......... التمثال رائع.\n4. ......... الشجرة مثمرة.\n5. ......... طبيبان يعالجان المرضى.\n6. ......... معلمتان تعلمان الأطفال.\n7. ......... مصليان يقيمان الصلاة.\n8. ......... وردتان متفتحتان."},{"t":"تدريب (٣)","q":"اقرأ وحول من القريب إلى البعيد: (هذا مهندس ماهر -> ذلك مهندس ماهر، هذه عاملة نشيطة -> تلك عاملة نشيطة، هؤلاء تلاميذ مجتهدون -> أولئك تلاميذ مجتهدون، هؤلاء تلميذات مجتهدات -> أولئك تلميذات مجتهدات)."},{"t":"تدريب (٤)","q":"اكتب كل كلمة من الكلمات التالية في المكان المناسب لها (البنتان، طفلة، الأولاد، الأمهات، الفلاحان، طالب):\n1. هؤلاء ......... يربين أطفالهن.\n2. هؤلاء ......... يطيعون آباءهم وأمهاتهم.\n3. هاتان ......... تنظفان البيت.\n4. هذه ......... تتعلم المشي.\n5. هذا ......... يقرأ القصة.\n6. هذان ......... يزرعان الأرض."},{"t":"تدريب (٥)","q":"ضع اسم الإشارة المناسب في الفراغ:\n1. ......... الشباب يبنون الوطن بسواعدهم.\n2. ......... البنت تسعد أمها بنجاحها.\n3. ......... النحلة تعطي العسل مجاناً.\n4. ......... التلميذتان متفوقتان في الامتحان.\n5. ......... العداءان يركضان بسرعة فائقة."},{"t":"تدريب (٦)","q":"نشاط بطاقات للربط بين أسماء الإشارة (ذلك، تلك، هذان، هذه، هؤلاء) وأجزائها المكملة (النحل ينتقل من زهرة إلى زهرة، النحلة تمتص رحيق الأزهار، التلميذات يتعلمن من النحل النشاط، التلميذان يبتعدان من النحل خوفاً من لسعه، التلميذة تبتعد من النحل خوفاً من لسعه)."}]},{"name":"الاسم الموصول","items":[{"t":"تدريب (١)","q":"صل كل كلمة من العمود الأول (الذي، التي، الذين، اللاتي، اللذان، اللتان) بما يناسبها من العمود الثاني (تزرع الحقل فلاحة، ينظمون السير رجال المرور، يحمل الرسائل ساعي البريد، تبصر بهما هما العينان، يعلمن الأطفال من المعلمات، فازا في السباق هما اللاعبان الماهران)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بكتابة (الذي) أو (اللتان) أو (الذين) أو (اللاتي) أو (التي) أو (اللذان):\n1. أعجبت بالقصة ........ قرأتها.\n2. أحترم الطلاب ........ يجتهدون.\n3. سرتني التلميذات ........ تفوقن في الامتحان.\n4. هذان اللاعبان هما ........ نالا الإعجاب.\n5. هاتان البنتان هما ........ رتبتا المائدة.\n6. زرت الصديق ........ عاد من السفر."},{"t":"تدريب (٣)","q":"(«الذي يحافظ على صحته يسلم من المرض») — اجعل العبارة السابقة: ١- للمفردة المؤنثة، ٢- للمثنى المذكر، ٣- للمثنى المؤنث، ٤- لجمع المذكر، ٥- لجمع المؤنث."},{"t":"تدريب (٤)","q":"ضع أمام كل سؤال (١- من الذي يعالجك إذا مرضت؟ ٢- أين الكتب التي أهديتها إلى مدرستك؟ ٣- من الذين ذهبوا معك في الرحلة؟ ٤- أين التلميذان اللذان اشتركا في العمل التعاوني؟ ٥- أين التلميذتان اللتان ترتلان سورة النصر؟ ٦- أين التلميذات اللاتي فزن بالجائزة؟ ٧- أين التلاميذ الذين فازوا بالجائزة؟) رقم الجواب الذي يناسبه من قائمة الأجوبة."},{"t":"تدريب (٥)","q":"أكمل ما يلي بكتابة (اللاتي) أو (التي) أو (الذي) أو (اللذان):\nجاء المتسابق ........ فاز في السباق.\nجاءت المتسابقة ........ فازت في السباق.\nجاء المتسابقان ........ فازا في السباق.\nجاءت المتسابقات ........ فزن في السباق."}]},{"name":"الضمائر (الضمائر المنفصلة)","items":[{"t":"تدريب (١)","q":"قراءة جمل ضمائر المتكلمين (أنا، نحن)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بكتابة (أنا) أو (نحن):\n1. ......... أطباء مخلصون.\n2. ......... مهندسان ماهران.\n3. ......... ولد مطيع لأبي.\n4. ......... سائقتان متدربتان.\n5. ......... تلميذات مهذبات.\n6. ......... جنود أوفياء لتراب العراق."},{"t":"تدريب (٣)","q":"قراءة جمل ضمائر المخاطبين (أنتَ، أنتِ، أنتما، أنتم، أنتنّ)."},{"t":"تدريب (٤)","q":"أكمل ما يلي بكتابة (أنتَ) أو (أنتِ) أو (أنتما) أو (أنتم) أو (أنتنّ):\n1. ......... معلمان مخلصان.\n2. ......... جنود شجعان.\n3. ......... رسام ماهر.\n4. ......... رياضية نشيطة.\n5. ......... أمهات حنونات.\n6. ......... فائزتان ذكيتان."},{"t":"تدريب (٥)","q":"قراءة جمل ضمائر الغائبين (هو، هي، هما، هم، هنّ)."},{"t":"تدريب (٦)","q":"اكتب بدل الأسماء (هو) أو (هي) أو (هما) أو (هم) أو (هنّ):\n1. دجلة والفرات نهران. ......... نهران.\n2. زينب ونجوى وفاتن مهندسات. ......... مهندسات.\n3. كامل وعلي وحسن فلاحون. ......... فلاحون.\n4. ليلى وهند محاميتان. ......... محاميتان.\n5. الكتاب خير صديق. ......... خير صديق.\n6. فاطمة ذاهبة إلى المدرسة. ......... ذاهبة إلى المدرسة."},{"t":"تدريب (٧)","q":"ضع (هو) أو (هي) أو (هما) أو (هم) أو (هنّ) في الأماكن المناسبة لها من الجمل الآتية:\nالمعلم ......... الذي يربي الأجيال.\nالمعلمة ......... التي تربي الأجيال.\nالمعلمان ......... اللذان يربيان الأجيال.\nالمعلمتان ......... اللتان تربيان الأجيال.\nالمعلمون ......... الذين يربون الأجيال.\nالمعلمات ......... اللاتي يُربين الأجيال."},{"t":"تدريب (٨)","q":"اربط كل ضمير في العمود الأول (هي، هما، هنّ، هم، هو) بالعبارة التي تكمل معناه في العمود الثاني (معلمون مخلصون، معلمات مخلصات، معلم مخلص، معلمة مخلصة، معلمان مخلصان) متصلة بعبارة (يداً بيد من أجل وطن أجمل)."}]},{"name":"الضمائر المتصلة","items":[{"t":"تدريب (١)","q":"قراءة جمل مع ضمائر المتكلم المتصلة (التاء، نا)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بالضمير (ت) أو (نا):\n1. أنا نم....... مبكراً.\n2. أنا ودع....... صديقي في المطار.\n3. قالت سعاد: أنا وزينب تناول....... الفطور.\n4. قالت لبنى: أنا وصديقاتي قرأ....... قصة من قصص الأطفال."},{"t":"تدريب (٣)","q":"صل كل كلمة في العمود الأول (أنا، أنا وأصدقائي، أنا والتلميذات، نحن) بما يناسبها في العمود الثاني (أشرفنا على إعداد الحفلة، ودعنا المعلمة في آخر السنة، صفقنا للفريق الفائز، زرت المتحف العراقي)."},{"t":"تدريب (٤)","q":"قراءة جمل مع ضمائر المخاطب المتصلة."},{"t":"تدريب (٥)","q":"أكمل ما يلي بكتابة (تَ) أو (تِ) أو (تما) أو (تم) أو (تنّ):\n1. أنتَ عد....... إلى المنزل.\n2. أنتِ استمع....... إلى المعلمة.\n3. أنتما قدم....... الجائزة للمتفوق.\n4. أنتما يا سارة ويا سميرة قطف....... التفاحة.\n5. أنتم نجح....... في الامتحان.\n6. أنتنّ أنشد....... القصيدة."},{"t":"تدريب (٦)","q":"أكمل ما يلي بكتابة (لعب، جلس، قرأ، خدم، أشرف، رحّب) بعد تغيير الأفعال بما يناسب الكلام:\n1. أنتَ ....... بالكرة.\n2. أنتِ ....... على الكرسي.\n3. أنتما ....... القصة.\n4. يا هند ويا سعاد أنتما ....... الوطن بسعيكما واجتهادكما.\n5. أنتم ....... على إعداد الحفلة.\n6. أنتنّ ....... بالضيوف."},{"t":"تدريب (٧)","q":"صل كل ضمير في العمود الأول (أنتَ، أنتِ، أنتما، أنتم، أنتنّ) بالعبارة التي تكمل معناه في العمود الثاني (قرأتما الدرس، قرأتنّ الدرس، قرأتَ الدرس، قرأتم الدرس، قرأتِ الدرس)."}]},{"name":"استعمال الفعل الماضي مع الضمائر","items":[{"t":"تدريب (١)","q":"أكمل الفراغ كما في المثال المحلول (شرب أحمد وسامي الماء -> هما شربا الماء):\nكتب التلميذان مسائل الحساب. هما كتب....... مسائل الحساب.\nرسم سامي وأحمد منظراً. هما رسم....... منظراً.\nتناول الصديقان طعامهما. هما تناول....... طعامهما.\nحفظت الأختان القصيدة. هما حفظت....... القصيدة.\nقرأت فاطمة وزينب القصة. هما قرأت....... القصة."},{"t":"تدريب (٢)","q":"أكمل الفراغ كما في المثال المحلول (دافع الحرس الوطني عن الوطن -> هم دافعوا عن الوطن):\nرفع التلاميذ العلم العراقي. هم رفع....... العلم العراقي.\nتنزه الأصدقاء في الحديقة العامة. هم تنزه....... في الحديقة العامة.\nحرث الفلاحون الأرض. هم حرث....... الأرض.\nحضرت الأمهات حفل نهاية العام. هنّ حضر....... حفل نهاية العام.\nسهرت الممرضات على راحة المرضى. هنّ سهر....... على راحة المرضى.\nشاهدت الصديقات المباراة. هنّ شاهد....... المباراة."},{"t":"تدريب (٣)","q":"أكمل ما يلي بكتابة (صنع، نهض، استقبل، شارك، قطف) بعد تغيير الأفعال بما يناسب الكلام:\n1. النجاران ....... الكراسي.\n2. التلاميذ ....... في المعرض.\n3. الفلاحات ....... التفاح.\n4. البنتان ....... الضيف.\n5. العاملان ....... مبكرين."},{"t":"تدريب (٤)","q":"صل كل كلمة في العمود الأول (هما، هو، هي، هم، هنّ) بما يناسبها في العمود الثاني (أكلن الغداء بشهية، ركضوا نحو الهدف، لعب بالكرة، مشت على الرصيف، شاهدا تمثيلية جديدة)."}]},{"name":"استعمال الفعل المضارع مع الضمائر (ضمير المتكلم والمخاطب)","items":[{"t":"تدريب (١)","q":"قراءة جمل الفعل المضارع مع ضمائر المتكلم والمخاطب."},{"t":"تدريب (٢)","q":"أدخل الأفعال التالية في جملها وغير ما تراه مناسباً (يدافع، يقرأ، يشرب، يحترم، يطالع، يذهب) مع الضمائر (أنا، أنتَ، نحن، أنتما، أنتم، أنتنّ)."},{"t":"تدريب (٣)","q":"صل كل كلمة في العمود الأول (أنا، نحن، أنتَ، أنتِ، أنتما، أنتم، أنتنّ) بما يناسبها في العمود الثاني (نستقبل ضيوفنا بالترحيب، تسمع النصيحة، تغرسن الأزهار في الحديقة، تصومون شهر رمضان، أغلف كتبي ودفاتري، تشاهدين المباراة الرياضية، تسافران إلى الشمال في فصل الصيف)."},{"t":"تدريب (٤)","q":"ضع كل ضمير في العمود الأول (أنا، أنتَ، نحن، أنتِ، أنتما، أنتنّ، أنتم) بالمكان المناسب له من عبارات العمود الثاني (أكتب درسي، تكتبون درسكم، تكتبين درسكِ، نكتب درسنا، تكتب درسكَ، تكتبان درسكما، تكتبن درسكن)."},{"t":"تدريب (٥)","q":"استعمل الفعل (يذهب) مع الضمائر مراعياً ما يلزم من تغيير كما في المثال الأول (أنا أذهب إلى المدرسة) مع الضمائر (أنتَ، نحن، أنتِ، أنتنّ، أنتم)."},{"t":"تدريب (٦)","q":"ضع (أنا - أنتَ - نحن - أنتِ - أنتما - أنتنّ - أنتم) في الأماكن المناسبة لها من الجمل الآتية (....... أقول الحق، ....... تقولون الحق، ....... تقول الحق، ....... تقلن الحق، ....... نقول الحق، ....... تقولين الحق، ....... تقولان الحق)."}]},{"name":"استعمال الفعل المضارع مع الضمائر (ضمير الغائب)","items":[{"t":"تدريب (١)","q":"قراءة جمل الفعل المضارع مع ضمائر الغائب (هو، هما، هم، هنّ)."},{"t":"تدريب (٢)","q":"صل كل كلمة في العمود الأول (التلميذان، المسلمون، الطائرتان، التلميذات، الأسد) بما يناسبها في العمود الثاني (يأكل فريسته، يتسابقان، يفهمن الدرس، تحلقان في الجو، يحجون إلى بيت الله الحرام)."},{"t":"تدريب (٣)","q":"استعمل الفعل (يزرع) مع الضمائر كما هو موضح في المثال وغير ما يلزم من تغيير (هو يزرع القمح) مع (هي، هما، هم، هنّ)."},{"t":"تدريب (٤)","q":"ضع (هو، هي، هما، هم، هنّ) في الأماكن المناسبة لها من الجمل الآتية (....... يسافر إلى بغداد، ....... يسافرون إلى بغداد، ....... يسافرن إلى بغداد، ....... يسافران إلى بغداد، ....... تسافر إلى بغداد)."},{"t":"تدريب (٥)","q":"أكمل ما يلي بكتابة (يحترم، ينالان، تفرحان، يحبون، يصفقن) في المكان المناسب:\n1. العراقي ....... أخاه العراقي.\n2. هما ....... جائزة.\n3. هنّ ....... للفائزين.\n4. هم ....... المعلم.\n5. فائزة وهند ....... بنجاح أخيهما."},{"t":"تدريب (٦)","q":"أكمل ما يلي بكتابة (هما، هو، هم، هنّ، هي) في المكان المناسب:\n1. ....... يسيرون على الرصيف.\n2. ....... تحافظ على نظافة كتبها.\n3. ....... يجيد قراءة القرآن.\n4. ....... يسمعان النصيحة.\n5. ....... يشاركن أمهاتهن في تدبير المنزل."}]},{"name":"استعمال فعل الأمر مع الضمائر","items":[{"t":"تدريب (١)","q":"حوّل الطلب إلى صيغة فعل الأمر مع المخاطب:\n1. اطلب إلى صديقك أن يدرس: يا صديقي .......\n2. اطلب إلى سميرة أن تفتح النافذة: يا سميرة ....... نافذة الغرفة.\n3. اطلب إلى مازن ومحمد أن يلعبا معك بالكرة: يا مازن ويا محمد ....... معي بالكرة.\n4. اطلب إلى الأولاد أن يحترموا من هم أكبر سناً منهم: يا أولاد ....... من هم أكبر سناً منكم.\n5. اطلب إلى الطالبات أن يكتبن الدرس: يا طالبات ....... الدرس."},{"t":"تدريب (٢)","q":"أكمل ما يلي متبعاً المثال الأول (الذهاب: اذهب إلى الحفلة): (القراءة: ....... درسك جيداً، التعلم: ....... رياضة السباحة، القطف: ....... ثمار التفاح أيها الفلاح، الكتابة: ....... درسك، النهوض: ....... مبكراً)."},{"t":"تدريب (٣)","q":"أكمل ما يلي متبعاً المثال الأول (اعمل: يا حسن اعمل من أجل وطنك): (انتبه: يا سلمى ....... إلى المعلمة، احرص: يا ليث ....... على نظافة المدرسة، واظب: يا شباب ....... على التمرينات الرياضية، ساعد: يا سعاد ويا إيمان ....... أمكما، أسعف: أيتها الممرضات ....... المرضى)."},{"t":"تدريب (٤)","q":"ضع الأسماء المناسبة في أماكنها من الجمل الآتية (نظفوا أسنانكم، نظفي أسنانكِ، نظف أسنانكَ، نظفن أسنانكنّ، نظفا أسنانكما)."},{"t":"تدريب (٥)","q":"ضع كل كلمة من العمود الأول (انشري، ثابرا، ساعدا، ناموا، انهض، سافرن) في مكانها من الجمل الآتية:\n1. أيها الصغار ....... مبكرين.\n2. أيها التلميذ النشيط ....... مبكراً.\n3. أيتها الشمس ....... أشعتك.\n4. أيها التلميذان ....... على اجتهادكما.\n5. أيتها الفتيات ....... إلى الشمال صيفاً.\n6. أيتها البنتان ....... أمكما."},{"t":"تدريب (٦)","q":"أعد صياغة الجمل التالية على وفق المثال الأول وغير ما تراه مناسباً (يا أحمد مارس الرياضة كل صباح) مع (يا نور ويا سعاد، يا أحمد ويا سامي، يا فتيات، يا تلاميذ)."},{"t":"تدريب (٧)","q":"أكمل ما يلي على وفق المثال الأول وغير ما تراه مناسباً (١- طلب معلم اللغة العربية إلى تلاميذه أن يحفظوا النشيد، فقال: يا تلاميذ احفظوا النشيد) لبقية الحالات (٢- معلم الرسم لتلميذين، ٣- معلمة الرياضة للتلميذات، ٤- أم لابنتها عن نظافة البيت، ٥- أم لابنتها عن الابتعاد من النار، ٦- شرطي المرور لسائق السيارة، ٧- هند لصديقاتها عن غرس الأزهار)."},{"t":"تدريب (٨)","q":"قال الأب لولده: («احرص على وقتك وحضر دروسك بجد واجتهاد، واحترم الآخرين») — ١- اجعل الأب يخاطب ابنته، ٢- ولديه، ٣- أولاده، ٤- بناته، مع إجراء التغيير المناسب."},{"t":"تدريب (٩)","q":"اقرأ وأكمل جدول الأمر والنهي للمفرد والمثنى والجمع بنوعيه (اصدق / لا تكذب، اصدقي / لا تكتبي، اصدقا / لا تكتبا، اصدقوا / لا تكتبوا، اصدقن / لا تكتبن)."}]},{"name":"الجملة المثبتة والجملة المنفية","items":[{"t":"تدريب (١)","q":"اكتب (ما) أو (لا) في الفراغ المناسب: (....... عاد المسافر، ....... ربح التاجر في تجارته، ....... يلعب الفريق، ....... يسافر خالد بالطائرة، ....... أقطف الزهر، ....... أهمل واجبي، ....... ركبت القطار، ....... زرتُ عمّانَ)."},{"t":"تدريب (٢)","q":"أجب عن الأسئلة التالية بكلام مثبت مرة وبكلام منفي مرة أخرى:\n1. هل قطفت زهرة من الحديقة؟\n2. هل شاركت في المعرض؟\n3. هل زرتَ القاهرة؟\n4. هل زاركم أحد أمس؟"},{"t":"تدريب (٣)","q":"حول الكلام المنفي إلى كلام مثبت:\n1. ما ودعت صديقي عند سفره.\n2. لا أسافر إلى المصيف.\n3. ما شاهد أحمد المباراة.\n4. لا يأتي سمير لزيارتك.\n5. ما تفتحت أزهار الحديقة.\n6. لا ينبت العشب في الحقل."},{"t":"تدريب (٤)","q":"نشاط بطاقات الأسئلة والأجوبة المثبتة والمنفية، مثل الأنموذج (هل سافرت بالباخرة؟ نعم سافرت بالباخرة)."}]},{"name":"الاستفهام","items":[{"t":"تدريب (١)","q":"قراءة الأسئلة والأجوبة بأدوات الاستفهام (هل، الهمزة، متى، كيف، أين، من، ما، كم)."},{"t":"تدريب (٢)","q":"ضع أمام كل جواب رقم السؤال الذي يناسبه من الأسئلة (١- هل قرأت درس العلوم؟ ٢- متى ينضج العنب؟ ٣- أين تتعلم القراءة والكتابة؟ ٤- من يسوق السيارة؟ ٥- ما اسم صديقك؟ ٦- كيف أصبحت اليوم؟ ٧- كم عجلة للسيارة؟)."},{"t":"تدريب (٣)","q":"ضع سؤالاً لكل جواب مما يأتي:\n1. بغداد اسم عاصمة العراق (ما).\n2. أساعد المحتاجين من الناس (من).\n3. أحمل حقيبة (ماذا).\n4. فاز أحمد بالجائزة (بماذا).\n5. بنى أبو جعفر المنصور مدينة بغداد (من).\n6. يطالع التلاميذ دروسهم في المكتبة (أين).\n7. جاء خالد ضاحكاً (كيف).\n8. قرأت ثلاثة كتب (كم).\n9. نعم، أحافظ على البيئة المدرسية (هل).\n10. غداً يسافر أبي إلى البصرة (متى).\n11. التلاميذ أول الذين يحترمون حقوق الإنسان (من).\n12. لا، لا أحب الكسل (هل)."},{"t":"تدريب (٤)","q":"حوار هاتفي مع صديقك (مازن) — اكتب الأسئلة التي يجيب عنها (كيف .......؟ ما ....... أخرك ....... الدوام؟ وهل .......؟ متى ....... في المدرسة؟ أين ....... البارحة؟ من ....... معك؟ كم ....... انقطعت؟ ....... درسك؟)."}]},{"name":"الجملة الاسمية والجملة الفعلية","items":[{"t":"تدريب (١)","q":"خذ كلمة من السطر الأول (النمر، تمطر، القط، ينجح) واختر لها كلمة من السطر الثاني (أليف، المجد، مفترس، السماء)، ثم بين نوع الجملة."},{"t":"تدريب (٢)","q":"حول الجمل الاسمية التالية إلى جمل فعلية:\n1. التمر يكثر في العراق.\n2. العامل يقضي نهاره مكافحاً.\n3. العلم ينير الحياة.\n4. البنت تشكر والدها."},{"t":"تدريب (٣)","q":"حول الجمل الفعلية التالية إلى جمل اسمية:\n1. ربح المؤمنون.\n2. يتفتح الزهر في الحديقة.\n3. ناضل المخلصون في سبيل وطنهم.\n4. تسقط الأمطار في فصل الشتاء.\n5. يحب العراقيون وطنهم."},{"t":"تدريب (٤)","q":"(«الحمامة طائر لطيف، جسمها جميل الشكل، منقارها مدبب، تلتقط الحب وتطعم به الصغار، يحب الحمام الحرية، ويكره الحبس في الأقفاص») — ضع خطاً تحت الجمل الاسمية وخطين تحت الجمل الفعلية في النص السابق."}]},{"name":"تدريبات للمراجعة","items":[{"t":"تدريب (١)","q":"أكمل ما يلي متبعاً المثال الأول (أنتن تحافظن على صحتكن): (....... تسيران على رصيف الشارع، ....... تزورين زميلتك المريضة، ....... تحافظون على البيئة الصحية في المدرسة)."},{"t":"تدريب (٢)","q":"أكمل ما يلي بكتابة (هذا) أو (هذان) أو (هاتان) أو (هؤلاء): (....... الطبيب ماهر، ....... المعلمون مخلصون، ....... الأمهات يربين أطفالهن على حب الخير، ....... الحجرتان واسعتان، ....... الطالبان متفوقان)."},{"t":"تدريب (٣)","q":"اكتب كل كلمة من الكلمات التالية (البنتان، الطفلة، الأولاد، المهندسات) في المكان المناسب لها (هؤلاء ....... يشرفن على العمل، هؤلاء ....... يطيعون آباءهم وأمهاتهم، هاتان ....... تنظفان البيت، هذه ....... تتعلم المشي)."},{"t":"تدريب (٤)","q":"وزع الكلمات التالية على ثلاثة جداول، الأول للمفرد والثاني للمثنى والثالث للجمع: (كتابان، طيور، أسد، تلميذ، مجلتان، مراصد، معلمون، أقلام، حديقتان، صفان)."},{"t":"تدريب (٥)","q":"اقرأ النص وضع خطاً تحت المفرد وخطين تحت المثنى وثلاثة خطوط تحت الجمع («ذهبت مرة لزيارة صديق، فأدخلني حجرة لها أربعة شبابيك وبابان وجدرانها ناصعة البياض، وأرضها مفروشة بالبسط المصنوعة في العراق، وفيها كراسي مصفوفة، وفي أحد جوانبها خزانة كتب ووجدت والديه جالسين فذكرا لنا أخبار المخترعين وقصا علينا ما يشوّق المستمعين من الحكايات اللطيفة، والنوادر الطريفة»)."},{"t":"تدريب (٦)","q":"أكمل ما يلي بكتابة (الذين) أو (التي) أو (الذي) أو (اللذان) أو (اللتان) أو (اللاتي): (أحب التلميذ ....... يتفوق في دراسته، أثنيت على التلميذة ....... نالت الجائزة، كافأ المدير اللاعبين ....... فازوا في السباق، يعجبني الصديقان ....... يحافظان على أوقاتهما، أصغيت إلى المعلمات ....... تكلمن في الاحتفال، حضرت الشاعرتان ....... فازتا في المسابقة الأدبية)."},{"t":"تدريب (٧)","q":"أبدل بالأسماء المذكرة أسماء مؤنثة في الجمل الآتية: (١- فاز اللاعب، ٢- يرسم خالد خارطة العراق، ٣- حرص العامل على زيادة الإنتاج، ٤- يصغي محمد إلى محدثه)."},{"t":"تدريب (٨)","q":"أكمل ما يلي بكتابة (أ) أو (من) أو (ما) أو (هل) أو (أين) أو (كيف): (....... قضيت فصل الصيف؟ ....... جئت إلى المدرسة؟ ....... زارك أمس؟ ....... محمد نجح؟ ....... قرأت بعض قصص تاريخنا العريق؟ ....... في يدك يا خالد؟)."},{"t":"تدريب (٩)","q":"استخرج من النص السابق («جلس كسلان تحت ظل شجرة فرأى نملة تصعد على جذع الشجرة ولما قربت من آخر الجذع سقطت...») الكلمات المبدوءة بحروف شمسية، ثم الفظها واكتبها كتابة صحيحة."},{"t":"تدريب (١٠)","q":"وزع الكلمات التالية على جدولين أحدهما للمؤنث والآخر للمذكر: (عائشة، الأم، اليوم، العمل، الصحة، مصباح، منضدة، العالم، الطالب، القلم، سعاد، الفرس، الحصان، الصحراء)."}]}];
const GB={def:6,topics:[],q:{}};let gid=0;
GDATA.forEach((tp,i)=>{const ids=[];tp.items.forEach(it=>{gid++;ids.push(gid);GB.q[gid]={l:it.t+' — '+tp.name,q:it.q}});GB.topics.push({id:i+1,name:tp.name,n:ids})});
BANK['الصف الرابع|القواعد']=GB;
